import org.jsoup.nodes.TextNode;
import org.jsoup.helper.Validate;
import org.jsoup.internal.StringUtil;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class TextNodeTest {

    @Mock
    private Appendable accum;

    @Test
    public void nodeNameAsStringTest() {
        when(this.text()).thenReturn("test");
        assertEquals("text", this.nodeName());
    }

    @Test
    public void textAsStringTest() {
        when(this.nodeName()).thenReturn("test");
        assertEquals("test", this.text());
    }

    @Test
    public void textFromStringTest() {
        TextNode node = new TextNode("test");
        assertEquals("test", node.text());
    }

    @Test
    public void getWholeTextAsStringTest() {
        when(this.nodeName()).thenReturn("test");
        when(this.text()).thenReturn("text");
        assertEquals("text", this.getWholeText());
    }

    @Test
    public void isBlankFalseTest() {
        TextNode node = new TextNode("test");
        assertFalse(node.isBlank());
    }

    @Test
    public void isBlankTrueTest() {
        when(this.text()).thenReturn("");
        assertTrue(this.isBlank());
    }

    @Test
    public void splitTextOffsetZeroTest() {
        TextNode node = new TextNode("test");
        assertEquals(0, node.splitText(0));
    }

    @Test
    public void splitTextOffSetFromStartOfStringTest() {
        String s = "test";
        TextNode node = new TextNode(s);
        when(this.text()).thenReturn(s);
        assertEquals(1, node.splitText(1));
    }

    @Test
    public void outerHtmlHeadAndTailTest() {
        StringBuilder sb = new StringBuilder();
        try {
            this.outerHtmlHead(sb, 0, null);
            this.outerHtmlTail(sb, 0, null);
        } catch (IOException e) {
            fail("Unexpected IOException");
        }
    }

    @Test
    public void toStringAsStringTest() {
        when(this.nodeName()).thenReturn("test");
        when(this.text()).thenReturn("text");
        assertEquals("<test>text</test>", this.toString());
    }

    @Test
    public void cloneTextNodeTest() {
        TextNode node = new TextNode("test");
        TextNode cloned = node.clone();
        assertNotNull(cloned);
        assertEquals(node.nodeName(), cloned.nodeName());
        assertEquals(node.text(), cloned.text());
    }
}
